import { ref, computed, reactive } from 'vue';
export default {
  props: {
    loading: Boolean
  },
  emits: ['register'],
  setup(props, {
    emit
  }) {
    const username = ref('');
    const email = ref('');
    const password = ref('');
    const confirmPassword = ref('');
    const errors = reactive({
      username: [],
      email: [],
      password: [],
      confirmPassword: []
    });
    const generalError = ref('');
    const passwordMismatchError = computed(() => {
      return password.value !== confirmPassword.value ? ['Passwords do not match'] : [];
    });
    const clearError = field => {
      errors[field] = [];
      generalError.value = '';
    };
    const submitForm = () => {
      if (password.value !== confirmPassword.value) {
        errors.confirmPassword = ['Passwords do not match'];
        return;
      }
      emit('register', {
        username: username.value,
        email: email.value,
        password: password.value
      });
    };
    const setErrors = newErrors => {
      if (typeof newErrors === 'string') {
        generalError.value = newErrors;
      } else if (typeof newErrors === 'object') {
        Object.keys(newErrors).forEach(field => {
          if (field in errors) {
            errors[field] = Array.isArray(newErrors[field]) ? newErrors[field] : [newErrors[field]];
          } else {
            generalError.value = newErrors[field];
          }
        });
      }
    };
    return {
      username,
      email,
      password,
      confirmPassword,
      errors,
      generalError,
      passwordMismatchError,
      submitForm,
      clearError,
      setErrors
    };
  }
};
